    // off on its own, then the rest -- and the flat vertex list happens to
    // come to four, exactly the number of samples bound to the element.
    html: '<svg class="plot-d6a7b5" fill="currentColor" font-family="system-ui, sans-serif" font-size="10" text-anchor="middle" width="640" height="400" viewBox="0 0 640 400"><g aria-label="y-axis tick label" text-anchor="end" font-variant="tabular-nums" transform="translate(-8.5,0.5)"><text y="0.32em" transform="translate(40,370)">1.0</text><text y="0.32em" transform="translate(40,335)">1.2</text><text y="0.32em" transform="translate(40,300)">1.4</text><text y="0.32em" transform="translate(40,265)">1.6</text><text y="0.32em" transform="translate(40,230)">1.8</text><text y="0.32em" transform="translate(40,195)">2.0</text><text y="0.32em" transform="translate(40,159.99999999999997)">2.2</text><text y="0.32em" transform="translate(40,125.00000000000001)">2.4</text><text y="0.32em" transform="translate(40,89.99999999999999)">2.6</text><text y="0.32em" transform="translate(40,55.000000000000036)">2.8</text><text y="0.32em" transform="translate(40,20)">3.0</text></g><g aria-label="y-axis label" text-anchor="start" transform="translate(-36.5,-16.5)"><text y="0.71em" transform="translate(40,20)">↑ y</text></g><g aria-label="x-axis tick label" font-variant="tabular-nums" transform="translate(0.5,9.5)"><text y="0.71em" transform="translate(40,370)">0.0</text><text y="0.71em" transform="translate(136.66666666666666,370)">0.5</text><text y="0.71em" transform="translate(233.33333333333331,370)">1.0</text><text y="0.71em" transform="translate(330,370)">1.5</text><text y="0.71em" transform="translate(426.66666666666663,370)">2.0</text><text y="0.71em" transform="translate(523.3333333333334,370)">2.5</text><text y="0.71em" transform="translate(620,370)">3.0</text></g><g aria-label="x-axis label" text-anchor="end" transform="translate(17.5,27.5)"><text transform="translate(620,370)">t →</text></g><g aria-label="line" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round" transform="translate(0.5,0.5)"><path d="M40,370ZM426.667,20L620,20L620,195"></path></g></svg>',
    scales: { x: { type: 'linear', domain: [0, 3], range: [40, 620] }, y: { type: 'linear', domain: [1, 3], range: [370, 20] } },
