    html: '<svg class="plot-d6a7b5" fill="currentColor" font-family="system-ui, sans-serif" font-size="10" text-anchor="middle" width="640" height="400" viewBox="0 0 640 400"><g aria-label="y-axis tick label" text-anchor="end" font-variant="tabular-nums" transform="translate(-8.5,0.5)"><text y="0.32em" transform="translate(40,370)">0.0</text><text y="0.32em" transform="translate(40,326.25)">0.5</text><text y="0.32em" transform="translate(40,282.5)">1.0</text><text y="0.32em" transform="translate(40,238.75)">1.5</text><text y="0.32em" transform="translate(40,195)">2.0</text><text y="0.32em" transform="translate(40,151.25)">2.5</text><text y="0.32em" transform="translate(40,107.5)">3.0</text><text y="0.32em" transform="translate(40,63.75)">3.5</text><text y="0.32em" transform="translate(40,20)">4.0</text></g><g aria-label="y-axis label" text-anchor="start" transform="translate(-36.5,-16.5)"><text y="0.71em" transform="translate(40,20)">↑ y</text></g><g aria-label="x-axis tick label" font-variant="tabular-nums" transform="translate(0.5,9.5)"><text y="0.71em" transform="translate(40,370)">0.0</text><text y="0.71em" transform="translate(136.66666666666666,370)">0.5</text><text y="0.71em" transform="translate(233.33333333333331,370)">1.0</text><text y="0.71em" transform="translate(330,370)">1.5</text><text y="0.71em" transform="translate(426.66666666666663,370)">2.0</text><text y="0.71em" transform="translate(523.3333333333334,370)">2.5</text><text y="0.71em" transform="translate(620,370)">3.0</text></g><g aria-label="x-axis label" text-anchor="end" transform="translate(17.5,27.5)"><text transform="translate(620,370)">t →</text></g><g aria-label="area"><path d="M40,282.5L40,370ZM426.667,107.5L620,107.5L620,195L620,370L620,370L426.667,370Z"></path></g></svg>',
